import React, { useEffect, useState } from 'react';
import { supabase } from '../../Database/Supabase';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import { MyNavbar } from '../../Components/MyNavbar/MyNavbar';

const DeleteImg = () => {
  const [avisos, setAvisos] = useState([]);
  const [mensaje, setMensaje] = useState('');

  useEffect(() => {
    fetchAvisos();
  }, []);

  const fetchAvisos = async () => {
    const { data, error } = await supabase
      .from('avisos')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) {
      setMensaje('Error al cargar avisos: ' + error.message);
    } else {
      setAvisos(data);
    }
  };

  const handleDelete = async (aviso) => {
    const filePath = aviso.image_url.split('/').slice(-2).join('/'); // ej: avisos/123456.jpg

    // 1. Borrar del storage
    const { error: storageError } = await supabase
      .storage
      .from('imgbusqueda')
      .remove([filePath]);

    if (storageError) {
      setMensaje('Error al borrar del storage: ' + storageError.message);
      return;
    }

    // 2. Borrar del registro
    const { error: dbError } = await supabase
      .from('avisos')
      .delete()
      .eq('id', aviso.id);

    if (dbError) {
      setMensaje('Error al borrar aviso: ' + dbError.message);
    } else {
      setMensaje('Aviso eliminado correctamente.');
      fetchAvisos();
    }
  };

  const esViejo = (fecha) => {
    const ahora = new Date();
    const creado = new Date(fecha);
    const diferencia = (ahora - creado) / (1000 * 60 * 60 * 24); // días
    return diferencia > 14;
  };

  return (
    <>
    <MyNavbar/>

    <div className="container mt-5">
      <h3 className="mb-4">Lista de Avisos</h3>

      {mensaje && (
        <div className={`alert ${mensaje.includes('Error') ? 'alert-danger' : 'alert-success'}`}>
          {mensaje}
        </div>
      )}

      <div className="table-responsive">
        <table className="table table-bordered align-middle text-center">
          <thead className="table-light">
            <tr>
              <th>Imagen</th>
              <th>Zona</th>
              <th>Ubicación</th>
              <th>Asignatura</th>
              <th>Fecha de subida</th>
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody>
            {avisos.map((aviso) => (
              <tr key={aviso.id}>
                <td>
                  <img src={aviso.image_url} alt="aviso" style={{ width: '60px', height: '60px', objectFit: 'cover' }} />
                </td>
                <td>{aviso.zona}</td>
                <td>{aviso.ubicacion}</td>
                <td>{aviso.asignatura}</td>
                <td>
                  {format(new Date(aviso.created_at), "d 'de' MMMM yyyy", { locale: es })}
                  {esViejo(aviso.created_at) && <span style={{ color: 'red', marginLeft: 8 }}>⚠️</span>}
                </td>
                <td>
                  <button className="btn btn-sm btn-danger" onClick={() => handleDelete(aviso)}>
                    Borrar
                  </button>
                </td>
              </tr>
            ))}
            {avisos.length === 0 && (
              <tr>
                <td colSpan="6" className="text-center">No hay avisos cargados.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
    
    
    </>
  );
};

export { DeleteImg };
